"use client";

import { useEffect } from "react";
import { mountLaserCursor } from "@/lib/oneko/laser-cursor-dom";

export function LaserCursor({ zIndex }: { zIndex: number }) {
  useEffect(() => mountLaserCursor(zIndex), [zIndex]);
  return null;
}

"use client";

/**
 * Installable React component — the classic “cat follows the cursor” idea comes from
 * oneko.js (MIT): https://github.com/adryd325/oneko.js/
 */

import { useEffect, useRef, useState } from "react";
import { LaserCursor } from "@/components/laser-cursor";
import { useCatAnimation } from "@/hooks/use-cat-animation";
import { useOnekoPropsSync } from "@/hooks/use-oneko-props-sync";
import {
  BUBBLE_COOLDOWN_FRAMES,
  BUBBLE_DISPLAY_FRAMES,
  DEFAULT_ANIMATION_SPEED,
  DEFAULT_BUBBLE_CHANCE,
  DEFAULT_FOLLOW_DISTANCE,
  DEFAULT_IDLE_THRESHOLD_MS,
  DEFAULT_OPACITY,
  DEFAULT_ROTATION_AMOUNT,
  DEFAULT_SCALE,
  DEFAULT_SPEED,
  DEFAULT_VOLUME,
  DEFAULT_Z_INDEX,
  FREERUN_CHANCE,
  FREERUN_DURATION,
} from "@/lib/oneko/constants";
import { createInitialCatState } from "@/lib/oneko/initial-state";
import type { CatActivityState, CatLiveState, OnekoProps } from "@/lib/oneko/types";

export type { CatActivityState, CatLiveState, OnekoProps };
export type { OnekoSkin } from "@/lib/oneko/skins";
export type { OnekoZone } from "@/lib/oneko/zones";

export default function Oneko({
  paused = false,
  followCursor = true,
  sleepEnabled = true,
  bubblePlacement = "auto",
  bubbleScale = 1,
  soundBasePath = "/cat-sounds",
  storageKey = "oneko",
  zones,
  zoneAttractionChance,
  zoneAttractionDuration,
  skin = "classic",
  spriteSrc,
  persistPosition = true,
  /** One below max so fixed UI can sit above the cat. */
  zIndex = DEFAULT_Z_INDEX,
  initialPos,
  speed = DEFAULT_SPEED,
  scale = DEFAULT_SCALE,
  opacity = DEFAULT_OPACITY,
  rotationAmount = DEFAULT_ROTATION_AMOUNT,
  idleThreshold = DEFAULT_IDLE_THRESHOLD_MS,
  meow = true,
  onStateChange,
  freerunChance = FREERUN_CHANCE,
  freerunDuration = FREERUN_DURATION,
  bubbleEnabled = true,
  bubbleDisplayFrames = BUBBLE_DISPLAY_FRAMES,
  bubbleCooldown = BUBBLE_COOLDOWN_FRAMES,
  hueRotate = 0,
  liveStateRef,
  bubbleChance = DEFAULT_BUBBLE_CHANCE,
  followDistance = DEFAULT_FOLLOW_DISTANCE,
  animationSpeed = DEFAULT_ANIMATION_SPEED,
  bubbleText = "",
  volume = DEFAULT_VOLUME,
  laserPointer = false,
}: OnekoProps) {
  const elRef = useRef<HTMLDivElement | null>(null);
  const lastStateRef = useRef<CatActivityState>("idle");
  const onStateChangeRef = useRef(onStateChange);

  useEffect(() => {
    onStateChangeRef.current = onStateChange;
  }, [onStateChange]);

  const config = {
    paused,
    followCursor,
    sleepEnabled,
    bubblePlacement,
    bubbleScale,
    soundBasePath,
    zones,
    zoneAttractionChance,
    zoneAttractionDuration,
    speed,
    scale,
    opacity,
    rotationAmount,
    idleThreshold,
    freerunChance,
    freerunDuration,
    bubbleEnabled,
    bubbleDisplayFrames,
    bubbleCooldown,
    bubbleChance,
    followDistance,
    animationSpeed,
    bubbleText,
    meow,
    volume,
    laserPointer: laserPointer && followCursor && !paused,
  };

  const [initialState] = useState(() => createInitialCatState({ initialPos, ...config }));
  const stateRef = useRef(initialState);

  useCatAnimation({
    stateRef,
    elRef,
    lastStateRef,
    onStateChangeRef,
    liveStateRef,
    persistPosition,
    storageKey,
    zIndex,
  });
  useOnekoPropsSync(stateRef, elRef, {
    ...config,
    hueRotate,
    skin,
    spriteSrc,
  });

  return config.laserPointer ? <LaserCursor zIndex={zIndex} /> : null;
}

"use client";

import { useEffect } from "react";
import { startCatAnimation } from "@/lib/oneko/start-cat-animation";
import type { CatActivityState, CatLiveState, CatRuntimeState } from "@/lib/oneko/types";

export function useCatAnimation({
  stateRef,
  elRef,
  lastStateRef,
  onStateChangeRef,
  liveStateRef,
  persistPosition,
  storageKey,
  zIndex,
}: {
  stateRef: { current: CatRuntimeState };
  elRef: { current: HTMLDivElement | null };
  lastStateRef: { current: CatActivityState };
  onStateChangeRef: { current: ((state: CatActivityState) => void) | undefined };
  liveStateRef?: { current: CatLiveState };
  persistPosition: boolean;
  storageKey: string;
  zIndex: number;
}) {
  useEffect(() => {
    if (typeof window === "undefined") {
      return;
    }

    const prefersReduced =
      window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches ?? false;
    if (prefersReduced) {
      return;
    }

    return startCatAnimation({
      stateRef,
      elRef,
      lastStateRef,
      onStateChangeRef,
      liveStateRef,
      persistPosition,
      storageKey,
      zIndex,
    });
  }, [
    stateRef,
    elRef,
    lastStateRef,
    onStateChangeRef,
    persistPosition,
    storageKey,
    zIndex,
    liveStateRef,
  ]);
}

import { useEffect, useRef } from "react";

/** Soften sprite changes without affecting movement, scale, or the selected tint. */
export function useSpriteAppearance(
  elRef: { current: HTMLElement | null },
  source: string,
  hueRotate = 0,
) {
  const previous = useRef<{ el: HTMLElement; source: string; filter: string } | null>(null);
  const transition = useRef<Animation | null>(null);

  // Check the element too: the animation engine can remount its DOM independently.
  useEffect(() => {
    const el = elRef.current;
    if (!el) return;
    const filter = hueRotate ? `hue-rotate(${hueRotate}deg)` : "blur(0px)";
    const last = previous.current;
    if (last?.el === el && last.source === source && last.filter === filter) return;

    transition.current?.cancel();
    transition.current = null;
    el.style.backgroundImage = `url(${JSON.stringify(source)})`;
    el.style.filter = filter;
    previous.current = { el, source, filter };

    if (
      last?.el === el &&
      last.source !== source &&
      !window.matchMedia("(prefers-reduced-motion: reduce)").matches &&
      typeof el.animate === "function"
    ) {
      transition.current = el.animate(
        [{ filter: `${filter} blur(2px)` }, { filter: `${filter} blur(0px)` }],
        { duration: 220, easing: "ease-out" },
      );
    }
  });

  useEffect(() => () => transition.current?.cancel(), []);
}

import { useEffect } from "react";
import { useSpriteAppearance } from "@/hooks/use-sprite-appearance";
import { applyRuntimeConfig, type CatRuntimeConfig } from "@/lib/oneko/runtime-config";
import { getSkinSource, type OnekoSkin } from "@/lib/oneko/skins";
import type { CatRuntimeState } from "@/lib/oneko/types";

type SyncableProps = CatRuntimeConfig & { hueRotate: number; skin: OnekoSkin; spriteSrc?: string };

export function useOnekoPropsSync(
  stateRef: { current: CatRuntimeState },
  elRef: { current: HTMLDivElement | null },
  props: SyncableProps,
) {
  useSpriteAppearance(elRef, props.spriteSrc || getSkinSource(props.skin), props.hueRotate);

  // Reapply after a render, including when the animation DOM is remounted.
  useEffect(() => {
    const state = stateRef.current;
    applyRuntimeConfig(state, props);
    const el = elRef.current;
    if (!el) return;
    el.style.transform = `scale(${props.scale}) rotate(${state.currentRotation}deg)`;
    el.style.opacity = String(props.opacity);
  });
}

import type { CatRuntimeState } from "./types";

/** The sprite has ten frames per second; no need to wake on every screen refresh. */
export function startAnimationLoop(
  stateRef: { current: CatRuntimeState },
  frame: () => void,
): () => void {
  let timer: ReturnType<typeof setInterval> | undefined;
  const syncVisibility = () => {
    clearInterval(timer);
    timer = undefined;
    if (document.hidden) return;
    timer = setInterval(() => {
      if (!stateRef.current.paused && !stateRef.current.pausedCfg) frame();
    }, 100);
  };
  document.addEventListener("visibilitychange", syncVisibility);
  syncVisibility();
  return () => {
    clearInterval(timer);
    document.removeEventListener("visibilitychange", syncVisibility);
  };
}

import type { CatActivityState, CatRuntimeState } from "../types";
import type { CatAnimationDeps } from "./deps";

export function getActivityLabel(deps: CatAnimationDeps): CatActivityState {
  const s = deps.stateRef.current;
  if (s.freerunMode) {
    return "freerun";
  }
  if (s.idleAnimation === "sleeping") {
    return "sleeping";
  }
  if (s.idleAnimation) {
    return s.idleAnimation;
  }
  if (s.idleTime > 0) {
    return "idle";
  }
  return "moving";
}

export function getBubbleStatus(s: CatRuntimeState) {
  if (s.bubbleVisible) {
    return "showing";
  }
  if (s.bubbleCooldown > 0) {
    return `cd ${s.bubbleCooldown}f`;
  }
  return "ready";
}

export function playSound(deps: CatAnimationDeps, pool: string[]) {
  const s = deps.stateRef.current;
  if (!s.enableMeow || s.soundCooldown > 0 || pool.length === 0) return;
  const url = pool[Math.floor(Math.random() * pool.length)];
  const filename = url.slice(url.lastIndexOf("/") + 1);
  const audio = new Audio(`${s.soundBasePathCfg}/${filename}`);
  audio.volume = s.soundVolumeCfg;
  s.soundCooldown = 20;
  audio.play().catch(() => {
    s.soundCooldown = 0;
  });
}

import {
  ALERT_MESSAGES,
  CIRCLE_LOOP_MESSAGES,
  IDLE_MESSAGES,
  MOUSE_LOOP_WINDING_TRIGGER,
  MOVING_MESSAGES,
  SCRATCHING_MESSAGES,
  SLEEPING_MESSAGES,
  TILE,
  TIRED_MESSAGES,
  WALL_SCRATCH_MESSAGES,
} from "../constants";
import type { CatAnimationDeps } from "./deps";

export function pickFromPool(deps: CatAnimationDeps, pool: readonly string[]) {
  const s = deps.stateRef.current;
  let idx = Math.floor(Math.random() * pool.length);
  if (idx === s.lastBubbleMsg) {
    idx = (idx + 1) % pool.length;
  }
  s.lastBubbleMsg = idx;
  return pool[idx];
}

function messageForIdleAnimation(deps: CatAnimationDeps): string | undefined {
  const s = deps.stateRef.current;

  if (s.idleAnimation === "sleeping") {
    return pickFromPool(deps, SLEEPING_MESSAGES);
  }
  if (typeof s.customBubbleText === "string") {
    if (s.customBubbleText.trim()) return s.customBubbleText;
  } else {
    const thoughts = [...new Set(s.customBubbleText.filter((text) => text.trim()))];
    if (thoughts.length) return pickFromPool(deps, thoughts);
  }
  if (s.idleAnimation === "tired") {
    return pickFromPool(deps, TIRED_MESSAGES);
  }
  if (s.idleAnimation === "scratchSelf") {
    return pickFromPool(deps, SCRATCHING_MESSAGES);
  }
  if (s.idleAnimation === "alert") {
    return pickFromPool(deps, ALERT_MESSAGES);
  }
  if (s.idleAnimation?.startsWith("scratchWall")) {
    return pickFromPool(deps, WALL_SCRATCH_MESSAGES);
  }

  return undefined;
}

function messageForActivity(deps: CatAnimationDeps): string {
  const s = deps.stateRef.current;
  const idleAnimationMessage = messageForIdleAnimation(deps);
  if (idleAnimationMessage) {
    return idleAnimationMessage;
  }
  if (s.idleTime > 0) {
    return pickFromPool(deps, IDLE_MESSAGES);
  }
  if (Math.abs(s.mouseCircleWinding) >= MOUSE_LOOP_WINDING_TRIGGER) {
    return pickFromPool(deps, CIRCLE_LOOP_MESSAGES);
  }
  return pickFromPool(deps, MOVING_MESSAGES);
}

function pickBubbleMessage(deps: CatAnimationDeps) {
  return messageForActivity(deps);
}

export function showBubble(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  s.bubbleVisible = true;
  s.bubbleTimer = s.bubbleDisplayFramesCfg;
  deps.bubbleTextEl.textContent = pickBubbleMessage(deps);
  deps.bubbleEl.style.opacity = "1";
}

export function hideBubble(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  s.bubbleVisible = false;
  deps.bubbleEl.style.opacity = "0";
  s.bubbleCooldown = s.bubbleCooldownFramesCfg;
}

function applyBubblePlacement(deps: CatAnimationDeps, showBelow: boolean) {
  deps.bubbleEl.style.transformOrigin = "top center";
  deps.bubbleEl.style.flexDirection = showBelow ? "column-reverse" : "column";
  deps.bubbleTail.style.cssText = showBelow
    ? "transform:scaleY(-1);margin-top:0;margin-bottom:-2px;"
    : "transform:none;margin-top:-2px;margin-bottom:0;";
}

function positionBubble(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  const catX = Math.floor(s.nekoPosX);
  const catY = Math.floor(s.nekoPosY);
  const vw = window.innerWidth;
  const vh = window.innerHeight;
  const bubbleW = deps.bubbleEl.offsetWidth || deps.bubbleTextEl.offsetWidth || 100;
  const bubbleH = deps.bubbleEl.offsetHeight || 34;
  const bubbleScale = s.scale * s.bubbleScaleCfg;
  const margin = 6;
  const halfCat = (TILE * s.scale) / 2;

  const aboveY = Math.floor(catY - halfCat - 8 - bubbleH * bubbleScale);
  const belowY = Math.floor(catY + halfCat + 8);
  const showBelow =
    s.bubblePlacementCfg === "below" ||
    (s.bubblePlacementCfg === "auto" && aboveY < margin && catY < vh / 2);
  const top = Math.max(
    margin,
    Math.min(vh - margin - bubbleH * bubbleScale, showBelow ? belowY : aboveY),
  );
  deps.bubbleEl.style.top = `${Math.round(top)}px`;
  deps.bubbleEl.style.transform = `translateX(-50%) scale(${bubbleScale})`;
  applyBubblePlacement(deps, showBelow);

  const halfBubble = (bubbleW * bubbleScale) / 2;
  let left = catX;
  if (halfBubble * 2 > vw - margin * 2) {
    left = vw / 2;
  } else if (catX - halfBubble < margin) {
    left = margin + halfBubble;
  } else if (catX + halfBubble > vw - margin) {
    left = vw - margin - halfBubble;
  }
  deps.bubbleEl.style.left = `${Math.round(left)}px`;
}

function tickVisibleBubble(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  s.bubbleTimer -= 1;
  if (s.bubbleTimer <= 0) {
    hideBubble(deps);
  }
}

function tickBubbleCooldown(deps: CatAnimationDeps) {
  deps.stateRef.current.bubbleCooldown -= 1;
}

function shouldTriggerBubble(deps: CatAnimationDeps): boolean {
  const s = deps.stateRef.current;
  const idleFrameThreshold = Math.max(1, Math.round(s.idleThresholdMs / 100));
  const idleRate = s.bubbleChanceCfg * 0.16;
  const moveRate = s.bubbleChanceCfg * 0.01;
  const loopW = Math.abs(s.mouseCircleWinding);
  const loopComplaining = s.idleTime === 0 && loopW >= MOUSE_LOOP_WINDING_TRIGGER;
  const moveRateBoost = loopComplaining ? 4.2 : 1;

  if (s.idleTime > idleFrameThreshold && Math.random() < idleRate) {
    return true;
  }
  return s.idleTime === 0 && Math.random() < moveRate * moveRateBoost;
}

export function updateBubble(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  if (!s.bubbleEnabledCfg) {
    if (s.bubbleVisible) {
      hideBubble(deps);
    }
    return;
  }

  positionBubble(deps);

  if (s.bubbleVisible) {
    tickVisibleBubble(deps);
    return;
  }

  if (s.bubbleCooldown > 0) {
    tickBubbleCooldown(deps);
    return;
  }

  if (shouldTriggerBubble(deps)) {
    showBubble(deps);
  }
}

import { CELL_SIZE, debugColor } from "../constants";
import type { ObstacleRect, PathPoint } from "../types";
import { getActivityLabel, getBubbleStatus } from "./activity";
import type { CatAnimationDeps } from "./deps";

const SVG_NS = "http://www.w3.org/2000/svg";

function clearSVGGroup(deps: CatAnimationDeps, id: string) {
  const group = deps.debugSVG.querySelector(`#${id}`);
  if (group) {
    group.innerHTML = "";
  }
}

function updateBlockedCells(deps: CatAnimationDeps, grid: Uint8Array, cols: number, rows: number) {
  const group = deps.debugSVG.querySelector("#oneko-blocked");
  if (!group) {
    return;
  }
  group.innerHTML = "";
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (grid[r * cols + c] === 1) {
        const rect = document.createElementNS(SVG_NS, "rect");
        rect.setAttribute("x", String(c * CELL_SIZE + 0.5));
        rect.setAttribute("y", String(r * CELL_SIZE + 0.5));
        rect.setAttribute("width", String(CELL_SIZE - 1));
        rect.setAttribute("height", String(CELL_SIZE - 1));
        rect.setAttribute("fill", "none");
        rect.setAttribute("stroke", debugColor.dangerSoft);
        rect.setAttribute("stroke-width", "0.5");
        group.appendChild(rect);
      }
    }
  }
}

function updateObstacleOutlines(deps: CatAnimationDeps, rects: ObstacleRect[]) {
  const group = deps.debugSVG.querySelector("#oneko-obstacles");
  if (!group) {
    return;
  }
  group.innerHTML = "";
  for (const r of rects) {
    const rect = document.createElementNS(SVG_NS, "rect");
    rect.setAttribute("x", String(r.left));
    rect.setAttribute("y", String(r.top));
    rect.setAttribute("width", String(r.right - r.left));
    rect.setAttribute("height", String(r.bottom - r.top));
    rect.setAttribute("fill", "none");
    rect.setAttribute("stroke", debugColor.dangerSoft);
    rect.setAttribute("stroke-width", "0.5");
    rect.setAttribute("stroke-dasharray", "3 3");
    group.appendChild(rect);
  }
}

function updateDebugPath(deps: CatAnimationDeps, path: PathPoint[], catX: number, catY: number) {
  const group = deps.debugSVG.querySelector("#oneko-path");
  if (!group) {
    return;
  }
  group.innerHTML = "";
  if (path.length === 0) {
    return;
  }

  const points = `${catX},${catY} ${path.map((p) => `${p.x},${p.y}`).join(" ")}`;
  const line = document.createElementNS(SVG_NS, "polyline");
  line.setAttribute("points", points);
  line.setAttribute("fill", "none");
  line.setAttribute("stroke", debugColor.trail);
  line.setAttribute("stroke-width", "1.5");
  line.style.transition = "all 0.15s ease";
  group.appendChild(line);

  for (const pt of path) {
    const dot = document.createElementNS(SVG_NS, "circle");
    dot.setAttribute("cx", String(pt.x));
    dot.setAttribute("cy", String(pt.y));
    dot.setAttribute("r", "2");
    dot.setAttribute("fill", debugColor.trailDot);
    group.appendChild(dot);
  }
}

function updateDebugHUD(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  const activity = getActivityLabel(deps);
  const stateColor = s.freerunMode ? debugColor.danger : debugColor.accent;
  const td = "padding:1px 0;";
  const labelTd = `${td}font-weight:bold;color:${debugColor.panelSubtle};padding-right:12px;`;
  const valueTd = `${td}text-align:right;`;
  const row = (label: string, value: string, color?: string) => {
    const valStyle = color ? `${valueTd}color:${color}` : valueTd;
    return `<tr><td style="${labelTd}">${label}</td><td style="${valStyle}">${value}</td></tr>`;
  };

  const speed = Math.hypot(s.nekoVelX, s.nekoVelY);
  const distToMouse = Math.hypot(s.mousePosX - s.nekoPosX, s.mousePosY - s.nekoPosY);

  deps.debugHUD.innerHTML = `<table style="border-collapse:collapse;width:100%">${[
    row("state", activity, stateColor),
    row("pos", `${Math.round(s.nekoPosX)}, ${Math.round(s.nekoPosY)}`),
    row("vel", `${s.nekoVelX.toFixed(1)}, ${s.nekoVelY.toFixed(1)}`),
    row("speed", speed.toFixed(1)),
    row("target", `${Math.round(s.mousePosX)}, ${Math.round(s.mousePosY)}`),
    row("dist", `${Math.round(distToMouse)}px`),
    row("idle", `${s.idleTime}f`),
    row("frame", `${s.frameCount}`),
    row("trail", `${s.currentPath.length} pts`),
    row("step", `${s.pathWaypointIdx}/${s.currentPath.length}`),
    row("obstacles", `${s.obstacleRects.length}`),
    row("grid", `${s.gridCols} x ${s.gridRows}`),
    row("freerun", s.freerunMode ? `${s.freerunTimer}f left` : "off"),
    row("bubble", getBubbleStatus(s)),
  ].join("")}</table>`;
}

export function createDebugRenderer(deps: CatAnimationDeps) {
  let lastBlockedGrid: Uint8Array | null = null;

  const renderDebug = () => {
    const s = deps.stateRef.current;
    if (s.grid !== lastBlockedGrid) {
      lastBlockedGrid = s.grid;
      if (s.grid) {
        updateBlockedCells(deps, s.grid, s.gridCols, s.gridRows);
      } else {
        clearSVGGroup(deps, "oneko-blocked");
      }
      updateObstacleOutlines(deps, s.obstacleRects);
    }
    updateDebugPath(deps, s.currentPath, s.nekoPosX, s.nekoPosY);
    updateDebugHUD(deps);
  };

  const maybeRenderDebug = () => {
    if (deps.stateRef.current.debugMode) {
      renderDebug();
    }
  };

  return { renderDebug, maybeRenderDebug };
}

import type { CatActivityState, CatLiveState, CatRuntimeState } from "../types";

export interface CatAnimationDeps {
  stateRef: { current: CatRuntimeState };
  el: HTMLDivElement;
  bubbleEl: HTMLDivElement;
  bubbleTextEl: HTMLDivElement;
  bubbleTail: HTMLDivElement;
  debugSVG: SVGSVGElement;
  debugHUD: HTMLDivElement;
  lastStateRef: { current: CatActivityState };
  onStateChangeRef: { current: ((state: CatActivityState) => void) | undefined };
  liveStateRef?: { current: CatLiveState };
}

import { refreshZones, updateZoneTarget } from "../zone-runtime";
import { createDebugRenderer } from "./debug-render";
import type { CatAnimationDeps } from "./deps";
import { tickLiveState } from "./frame/tick-live-state";
import { tickMovement } from "./frame/tick-movement";
import { tickPrelude } from "./frame/tick-prelude";
import { tickSounds } from "./frame/tick-sounds";

export function createFrameLoop(deps: CatAnimationDeps) {
  const { maybeRenderDebug } = createDebugRenderer(deps);

  const frame = () => {
    const s = deps.stateRef.current;
    if (s.pausedCfg) return;
    if (!refreshZones(deps)) return;
    tickPrelude(s);
    updateZoneTarget(s, window.innerWidth, window.innerHeight);
    const dist = Math.hypot(s.mousePosX - s.nekoPosX, s.mousePosY - s.nekoPosY);
    tickMovement(deps, dist);
    maybeRenderDebug();
    const currentState = tickSounds(deps);
    tickLiveState(deps, dist, currentState);
  };

  return frame;
}

import type { CatRuntimeState } from "../../types";

export function interruptIdleIfChasing(s: CatRuntimeState, dist: number) {
  if (s.idleAnimation && dist > 32 && !s.stateLocked && !s.noFollow) {
    s.idleAnimation = null;
    s.idleAnimationFrame = 0;
    s.idleTime = 0;
  }
}

import { LASER_CATCH_POOL } from "../../constants";
import { playSound } from "../activity";
import type { CatAnimationDeps } from "../deps";

export function tickLaser(deps: CatAnimationDeps, dist: number) {
  const s = deps.stateRef.current;
  if (!s.laserPointerCfg) {
    return;
  }

  const close = dist < s.followDistanceCfg + 4;
  if (close && !s.laserCaught) {
    s.laserCaught = true;
    playSound(deps, LASER_CATCH_POOL);
  } else if (!close && dist > s.followDistanceCfg + 24) {
    s.laserCaught = false;
  }
}

import type { CatActivityState } from "../../types";
import type { CatAnimationDeps } from "../deps";

export function tickLiveState(
  deps: CatAnimationDeps,
  dist: number,
  currentState: CatActivityState,
) {
  if (!deps.liveStateRef?.current) {
    return;
  }

  const s = deps.stateRef.current;
  const ls = deps.liveStateRef.current;
  ls.state = currentState;
  ls.posX = s.nekoPosX;
  ls.posY = s.nekoPosY;
  ls.velMag = Math.hypot(s.nekoVelX, s.nekoVelY);
  ls.idleTime = s.idleTime;
  ls.distToMouse = dist;
  ls.frameCount = s.frameCount;
  ls.freerunActive = s.freerunMode;
  ls.freerunTimer = s.freerunTimer;
  ls.bubbleVisible = s.bubbleVisible;
  ls.pathLength = s.currentPath.length;
  ls.obstacleCount = s.obstacleRects.length;
}

import { updateBubble } from "../bubbles";
import type { CatAnimationDeps } from "../deps";
import { recalcPathIfNeeded, refreshGridIfNeeded } from "../grid";
import { freezeLockedState, updateIdleAnimation } from "../idle";
import { followPath } from "../movement";
import { interruptIdleIfChasing } from "./interrupt-idle";
import { tickLaser } from "./tick-laser";

export function tickMovement(deps: CatAnimationDeps, dist: number) {
  const s = deps.stateRef.current;
  refreshGridIfNeeded(deps);
  const target = s.zoneState.movementTarget;
  const targetDistance = Math.hypot(target.x - s.nekoPosX, target.y - s.nekoPosY);
  interruptIdleIfChasing(s, targetDistance);
  recalcPathIfNeeded(deps);
  updateBubble(deps);
  tickLaser(deps, dist);

  if (!updateIdleAnimation(deps) && !freezeLockedState(deps)) {
    followPath(deps, targetDistance);
  }
}

import { MOUSE_LOOP_WINDING_DECAY } from "../../constants";
import type { CatRuntimeState } from "../../types";

export function tickPrelude(s: CatRuntimeState) {
  s.frameCount += 1;
  s.mouseCircleWinding *= MOUSE_LOOP_WINDING_DECAY;
  if (Math.abs(s.mouseCircleWinding) < 0.35) {
    s.mouseCircleWinding = 0;
    s.loopPrevAngle = null;
  }
  s.soundCooldown = Math.max(0, s.soundCooldown - 1);
}

import { SOUND_POOLS } from "../../constants";
import type { CatActivityState } from "../../types";
import { getActivityLabel, playSound } from "../activity";
import type { CatAnimationDeps } from "../deps";

function tickAmbientSounds(deps: CatAnimationDeps, currentState: CatActivityState) {
  const s = deps.stateRef.current;
  const { idleTime, frameCount } = s;

  if (currentState === "idle" && idleTime > 0 && idleTime % 60 === 0) {
    playSound(deps, SOUND_POOLS.idle);
  } else if (currentState === "sleeping" && frameCount % 100 === 0) {
    playSound(deps, SOUND_POOLS.sleeping);
  } else if (currentState === "moving" && frameCount % 80 === 0) {
    playSound(deps, SOUND_POOLS.moving);
  }
}

export function tickSounds(deps: CatAnimationDeps): CatActivityState {
  const currentState = getActivityLabel(deps);

  if (currentState !== deps.lastStateRef.current) {
    deps.lastStateRef.current = currentState;
    deps.onStateChangeRef.current?.(currentState);
    const pool = SOUND_POOLS[currentState];
    if (pool) {
      playSound(deps, pool);
    }
  }

  tickAmbientSounds(deps, currentState);
  return currentState;
}

import {
  CELL_SIZE,
  OBSTACLE_INTERVAL,
  PATH_RECALC_INTERVAL,
  PATH_RECALC_MOUSE_CELLS,
} from "../constants";
import { buildGrid, collectObstacles } from "../pathfinding";
import type { CatAnimationDeps } from "./deps";
import { recalculatePath } from "./movement";

export function refreshGridIfNeeded(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  if (s.frameCount - s.lastObstacleRefresh < OBSTACLE_INTERVAL) {
    return;
  }
  const softObstacles = collectObstacles().filter(
    (rect) =>
      !s.zoneState.favorites.some(
        ({ rect: favorite }) =>
          rect.left >= favorite.left &&
          rect.right <= favorite.right &&
          rect.top >= favorite.top &&
          rect.bottom <= favorite.bottom,
      ),
  );
  s.obstacleRects = [...softObstacles, ...s.zoneState.blocked];
  s.lastObstacleRefresh = s.frameCount;
  s.gridCols = Math.ceil(window.innerWidth / CELL_SIZE);
  s.gridRows = Math.ceil(window.innerHeight / CELL_SIZE);
  s.grid = buildGrid(s.obstacleRects, s.gridCols, s.gridRows);
  s.lastPathRecalcFrame = -PATH_RECALC_INTERVAL;
}

export function recalcPathIfNeeded(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  const mouseCol = Math.floor(s.zoneState.movementTarget.x / CELL_SIZE);
  const mouseRow = Math.floor(s.zoneState.movementTarget.y / CELL_SIZE);
  const mouseMoved =
    Math.abs(mouseCol - s.lastPathTargetCol) > PATH_RECALC_MOUSE_CELLS ||
    Math.abs(mouseRow - s.lastPathTargetRow) > PATH_RECALC_MOUSE_CELLS;
  if (s.frameCount - s.lastPathRecalcFrame >= PATH_RECALC_INTERVAL || mouseMoved) {
    recalculatePath(deps);
  }
}

import { defaultSpriteSets, IDLE_ANIMATION_DURATIONS, SLEEPING_MESSAGES } from "../constants";
import type { CatRuntimeState, IdleActivityState } from "../types";
import { pickFromPool } from "./bubbles";
import type { CatAnimationDeps } from "./deps";
import { clearRotation, setSprite } from "./sprites";

function idleFrameThreshold(s: CatRuntimeState) {
  return Math.max(1, Math.round(s.idleThresholdMs / 100));
}

function wallScratchAnimations(s: CatRuntimeState): IdleActivityState[] {
  return [
    s.nekoPosX <= 18 && "scratchWallW",
    s.nekoPosX >= window.innerWidth - 18 && "scratchWallE",
    s.nekoPosY <= 18 && "scratchWallN",
    s.nekoPosY >= window.innerHeight - 18 && "scratchWallS",
  ].filter(Boolean) as IdleActivityState[];
}

function pickRandomIdleAnimation(s: CatRuntimeState): IdleActivityState {
  const available: IdleActivityState[] = [
    "scratchSelf",
    ...(s.sleepEnabledCfg ? ["tired" as const] : []),
    ...wallScratchAnimations(s),
  ];
  return available[Math.floor(Math.random() * available.length)];
}

function startSleepingAnimation(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  s.idleAnimation = "sleeping";
  if (s.bubbleVisible) {
    deps.bubbleTextEl.textContent = pickFromPool(deps, SLEEPING_MESSAGES);
  }
}

export function maybeStartIdleAnimation(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  const threshold = idleFrameThreshold(s);
  if (s.idleAnimation != null || s.idleTime < threshold || Math.random() >= 0.1) {
    return;
  }

  s.idleAnimationFrame = 0;
  if (s.sleepEnabledCfg && s.idleTime > threshold * 3) {
    startSleepingAnimation(deps);
    return;
  }

  s.idleAnimation = pickRandomIdleAnimation(s);
}

function computeIdleSpriteIndex(
  animName: IdleActivityState,
  frame: number,
  animationSpeed: number,
): number {
  const sprites = defaultSpriteSets[animName as keyof typeof defaultSpriteSets];
  const baseDuration = IDLE_ANIMATION_DURATIONS[animName] ?? (sprites ? sprites.length * 8 : 8);
  const duration = Math.max(1, Math.round(baseDuration / animationSpeed));
  const frameCount = sprites?.length || 1;
  const framesPerSprite = Math.max(1, Math.floor(duration / frameCount));
  return Math.floor(frame / framesPerSprite) % frameCount;
}

function getIdleAnimationDuration(animName: IdleActivityState, animationSpeed: number): number {
  const sprites = defaultSpriteSets[animName as keyof typeof defaultSpriteSets];
  const baseDuration = IDLE_ANIMATION_DURATIONS[animName] ?? (sprites ? sprites.length * 8 : 8);
  return Math.max(1, Math.round(baseDuration / animationSpeed));
}

function resetOrLoopIdleAnimation(
  s: CatRuntimeState,
  animName: IdleActivityState,
  duration: number,
) {
  if (s.idleAnimationFrame < duration || animName === "sleeping") {
    return;
  }

  if (s.stateLocked || s.noFollow) {
    s.idleAnimationFrame = 0;
    return;
  }

  s.idleAnimation = null;
  s.idleAnimationFrame = 0;
}

export function updateIdleAnimation(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  if (!s.sleepEnabledCfg && (s.idleAnimation === "sleeping" || s.idleAnimation === "tired")) {
    s.idleAnimation = null;
    s.idleAnimationFrame = 0;
    s.idleTime = 0;
  }
  if (!s.idleAnimation) {
    return false;
  }

  const animName = s.idleAnimation;
  const spriteIndex = computeIdleSpriteIndex(animName, s.idleAnimationFrame, s.animationSpeedCfg);
  setSprite(deps, animName, spriteIndex);
  clearRotation(deps);
  s.idleAnimationFrame += 1;
  resetOrLoopIdleAnimation(s, animName, getIdleAnimationDuration(animName, s.animationSpeedCfg));
  return true;
}

export function freezeLockedState(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  if (!(s.stateLocked || s.noFollow) || (s.freerunMode && !s.noFollow)) {
    return false;
  }

  s.nekoVelX *= 0.5;
  s.nekoVelY *= 0.5;
  s.idleTime = Math.max(s.idleTime, 1);
  setSprite(deps, "idle", s.frameCount);
  clearRotation(deps);
  return true;
}

import { MOUSE_LOOP_MIN_STEP, MOUSE_LOOP_WINDING_CAP } from "../constants";
import type { CatAnimationDeps } from "./deps";

export function createMouseMoveHandler(deps: CatAnimationDeps) {
  return (ev: MouseEvent) => {
    const mx = ev.clientX;
    const my = ev.clientY;
    const s = deps.stateRef.current;
    const px = s.mousePosX;
    const py = s.mousePosY;
    const dx = mx - px;
    const dy = my - py;
    const dist = Math.hypot(dx, dy);
    if (dist >= MOUSE_LOOP_MIN_STEP) {
      const ang = Math.atan2(dy, dx);
      if (s.loopPrevAngle !== null) {
        let d = ang - s.loopPrevAngle;
        while (d > Math.PI) {
          d -= 2 * Math.PI;
        }
        while (d < -Math.PI) {
          d += 2 * Math.PI;
        }
        s.mouseCircleWinding += d;
        if (s.mouseCircleWinding > MOUSE_LOOP_WINDING_CAP) {
          s.mouseCircleWinding = MOUSE_LOOP_WINDING_CAP;
        } else if (s.mouseCircleWinding < -MOUSE_LOOP_WINDING_CAP) {
          s.mouseCircleWinding = -MOUSE_LOOP_WINDING_CAP;
        }
      }
      s.loopPrevAngle = ang;
    }
    s.mousePosX = mx;
    s.mousePosY = my;
  };
}

import { constrainZoneMovement } from "../zones";
import {
  CELL_SIZE,
  FREERUN_MESSAGES,
  MAX_VEL_FACTOR,
  STEER_LERP,
  TILE,
  WAYPOINT_REACH_DIST,
} from "../constants";
import { findRoute, nearestWalkable, worldToCell } from "../pathfinding";
import type { CatAnimationDeps } from "./deps";
import { maybeStartIdleAnimation } from "./idle";
import { clearRotation, directionFromDelta, setSprite } from "./sprites";

export function recalculatePath(deps: CatAnimationDeps): void {
  const s = deps.stateRef.current;
  const { grid, gridCols: cols, gridRows: rows } = s;
  if (!grid || cols === 0 || rows === 0) {
    s.currentPath = [];
    return;
  }

  const catCell = nearestWalkable(
    worldToCell(s.nekoPosX, s.nekoPosY, cols, rows),
    grid,
    cols,
    rows,
  );
  const mouseCell = nearestWalkable(
    worldToCell(s.zoneState.movementTarget.x, s.zoneState.movementTarget.y, cols, rows),
    grid,
    cols,
    rows,
  );

  s.currentPath = findRoute(catCell, mouseCell, grid, cols, rows);
  s.pathWaypointIdx = 0;
  s.lastPathRecalcFrame = s.frameCount;
  s.lastPathTargetCol = Math.floor(s.zoneState.movementTarget.x / CELL_SIZE);
  s.lastPathTargetRow = Math.floor(s.zoneState.movementTarget.y / CELL_SIZE);
}

function getNextWaypointTarget(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  const { currentPath: path } = s;
  if (path.length === 0) {
    return { x: s.zoneState.movementTarget.x, y: s.zoneState.movementTarget.y };
  }
  while (s.pathWaypointIdx < path.length - 1) {
    const wp = path[s.pathWaypointIdx];
    if (Math.hypot(wp.x - s.nekoPosX, wp.y - s.nekoPosY) < WAYPOINT_REACH_DIST) {
      s.pathWaypointIdx++;
    } else {
      break;
    }
  }
  return path[s.pathWaypointIdx];
}

function moveToward(deps: CatAnimationDeps, targetX: number, targetY: number) {
  const s = deps.stateRef.current;
  const dx = targetX - s.nekoPosX;
  const dy = targetY - s.nekoPosY;
  const dist = Math.hypot(dx, dy);
  if (dist < 1) {
    s.nekoVelX *= 0.5;
    s.nekoVelY *= 0.5;
    return;
  }
  const currentSpeed = s.currentSpeed;
  s.nekoVelX += ((dx / dist) * currentSpeed - s.nekoVelX) * STEER_LERP;
  s.nekoVelY += ((dy / dist) * currentSpeed - s.nekoVelY) * STEER_LERP;
  const velMag = Math.hypot(s.nekoVelX, s.nekoVelY);
  const maxVel = currentSpeed * MAX_VEL_FACTOR;
  const clampedMag = Math.min(velMag, maxVel);
  if (velMag > maxVel) {
    s.nekoVelX = (s.nekoVelX / velMag) * maxVel;
    s.nekoVelY = (s.nekoVelY / velMag) * maxVel;
  }
  const from = { x: s.nekoPosX, y: s.nekoPosY };
  const proposed = {
    x: Math.max(16, Math.min(window.innerWidth - 16, s.nekoPosX + s.nekoVelX)),
    y: Math.max(16, Math.min(window.innerHeight - 16, s.nekoPosY + s.nekoVelY)),
  };
  const safe = constrainZoneMovement(from, proposed, s.zoneState.blocked);
  if (safe.x !== proposed.x || safe.y !== proposed.y) {
    s.nekoVelX = 0;
    s.nekoVelY = 0;
  }
  if (safe.x === from.x && safe.y === from.y && (safe.x !== proposed.x || safe.y !== proposed.y)) {
    restNearCursor(deps);
    return;
  }
  s.nekoPosX = safe.x;
  s.nekoPosY = safe.y;
  s.nekoPosX = Math.max(16, Math.min(window.innerWidth - 16, s.nekoPosX));
  s.nekoPosY = Math.max(16, Math.min(window.innerHeight - 16, s.nekoPosY));
  deps.el.style.left = `${Math.floor(s.nekoPosX - TILE / 2)}px`;
  deps.el.style.top = `${Math.floor(s.nekoPosY - TILE / 2)}px`;
  const dir = directionFromDelta(s.nekoVelX, s.nekoVelY) ?? "idle";
  setSprite(deps, dir, s.frameCount);
  if (clampedMag > 0.5 && s.rotationAmount > 0) {
    const velAngle = Math.atan2(s.nekoVelY, s.nekoVelX) * (180 / Math.PI);
    s.currentRotation = (velAngle / 180) * s.rotationAmount;
  } else {
    s.currentRotation = 0;
  }
  deps.el.style.transform = `scale(${s.scale}) rotate(${s.currentRotation}deg)`;
  s.idleTime = 0;
}

function pickFreerunMessage(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  let idx = Math.floor(Math.random() * FREERUN_MESSAGES.length);
  if (idx === s.lastFreerunMsg) {
    idx = (idx + 1) % FREERUN_MESSAGES.length;
  }
  s.lastFreerunMsg = idx;
  return FREERUN_MESSAGES[idx];
}

function enterFreerun(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  s.freerunMode = true;
  s.freerunTimer = s.freerunDurationCfg;
  s.bubbleVisible = true;
  s.bubbleTimer = s.freerunDurationCfg;
  s.bubbleCooldown = 0;
  deps.bubbleTextEl.textContent = pickFreerunMessage(deps);
  deps.bubbleEl.style.opacity = "1";
}

function tickFreerun(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  s.freerunTimer -= 1;
  if (s.freerunTimer <= 0) {
    const keepAlive = s.stateLocked;
    s.freerunMode = keepAlive;
    if (keepAlive) {
      s.freerunTimer = s.freerunDurationCfg;
    }
  }
  moveToward(deps, s.zoneState.movementTarget.x, s.zoneState.movementTarget.y);
}

function restNearCursor(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  setSprite(deps, "idle", s.frameCount);
  clearRotation(deps);
  s.nekoVelX *= 0.5;
  s.nekoVelY *= 0.5;
  s.idleTime += 1;
  if (!(s.stateLocked || s.noFollow)) {
    s.freerunMode = false;
  }
  maybeStartIdleAnimation(deps);
}

function chaseCursor(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  if (s.freerunMode) {
    tickFreerun(deps);
    return;
  }
  if (!s.noFollow && Math.random() < s.freerunChanceCfg) {
    enterFreerun(deps);
    moveToward(deps, s.zoneState.movementTarget.x, s.zoneState.movementTarget.y);
    return;
  }
  const target = getNextWaypointTarget(deps);
  moveToward(deps, target.x, target.y);
}

export function followPath(deps: CatAnimationDeps, overallDist: number) {
  const s = deps.stateRef.current;
  const lastWaypoint = s.currentPath.at(-1);
  const reachedPathEnd =
    !s.freerunMode &&
    lastWaypoint &&
    s.pathWaypointIdx === s.currentPath.length - 1 &&
    Math.hypot(lastWaypoint.x - s.nekoPosX, lastWaypoint.y - s.nekoPosY) < s.followDistanceCfg;
  if (overallDist < s.followDistanceCfg || reachedPathEnd) {
    restNearCursor(deps);
    return;
  }
  chaseCursor(deps);
}

import { defaultSpriteSets, DIRECTION_RANGES, TILE } from "../constants";
import type { CatAnimationDeps } from "./deps";

export function setSprite(
  deps: CatAnimationDeps,
  name: keyof typeof defaultSpriteSets | string,
  frame: number,
) {
  const sprites = defaultSpriteSets[name as keyof typeof defaultSpriteSets];
  if (!sprites?.length) {
    return;
  }
  const sprite = sprites[frame % sprites.length];
  deps.el.style.backgroundPosition = `${sprite[0] * TILE}px ${sprite[1] * TILE}px`;
}

function getDirectionFromAngle(angle: number): string {
  if (angle >= 157.5 || angle < -157.5) {
    return "W";
  }
  for (const range of DIRECTION_RANGES) {
    if (angle >= range.min && angle < range.max) {
      return range.dir;
    }
  }
  return "E";
}

export function directionFromDelta(dx: number, dy: number) {
  if (Math.abs(dx) < 1 && Math.abs(dy) < 1) {
    return null;
  }
  return getDirectionFromAngle(Math.atan2(dy, dx) * (180 / Math.PI));
}

export function clearRotation(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  if (s.currentRotation !== 0) {
    s.currentRotation = 0;
    deps.el.style.transform = `scale(${s.scale}) rotate(0deg)`;
  }
}

import { debugColor } from "../constants";
import type { CatRuntimeState } from "../types";
import { makeBtn, makeRow, sectionLabel } from "./ui";

export function appendBubbleSection(
  body: HTMLElement,
  stateRef: { current: CatRuntimeState },
  bubbleEl: HTMLDivElement,
  bubbleTextEl: HTMLDivElement,
  showBubble: () => void,
  hideBubble: () => void,
  bubbleDisplayFrames: number,
) {
  body.appendChild(sectionLabel("bubble"));

  const showBubbleBtn = makeBtn("show", () => showBubble());
  const hideBubbleBtn = makeBtn("hide", () => hideBubble());
  body.appendChild(makeRow(showBubbleBtn, hideBubbleBtn));

  const bubbleInput = document.createElement("input");
  bubbleInput.type = "text";
  bubbleInput.placeholder = "custom text...";
  bubbleInput.style.cssText = [
    `background:${debugColor.controlBg}`,
    `border:1px solid ${debugColor.controlBorder}`,
    `color:${debugColor.panelText}`,
    "border-radius:4px",
    "padding:2px 6px",
    "font-family:inherit",
    "font-size:11px",
    "flex:1",
    "min-width:0",
  ].join(";");

  const setTextBtn = makeBtn("set", () => {
    if (bubbleInput.value.trim()) {
      bubbleTextEl.textContent = bubbleInput.value.trim();
      stateRef.current.bubbleVisible = true;
      stateRef.current.bubbleTimer = bubbleDisplayFrames;
      bubbleEl.style.opacity = "1";
    }
  });

  body.appendChild(makeRow(bubbleInput, setTextBtn));
}

import { debugColor } from "../constants";
import type { CatActivityState, CatRuntimeState, IdleActivityState } from "../types";
import { makeBtn, makeRow, sectionLabel, selectStyle } from "./ui";

const ALL_STATES = [
  "moving",
  "idle",
  "sleeping",
  "scratchSelf",
  "tired",
  "alert",
  "scratchWallN",
  "scratchWallS",
  "scratchWallE",
  "scratchWallW",
  "freerun",
] as const;

function applyForcedState(s: CatRuntimeState, chosen: CatActivityState, locked: boolean) {
  s.idleAnimation = null;
  s.idleAnimationFrame = 0;
  s.freerunMode = false;
  s.freerunTimer = 0;

  if (chosen === "moving") {
    s.idleTime = 0;
    s.stateLocked = locked;
    return;
  }

  if (chosen === "idle") {
    s.idleTime = 200;
    s.stateLocked = locked;
    return;
  }

  if (chosen === "freerun") {
    s.freerunMode = true;
    s.freerunTimer = 600;
    s.stateLocked = locked;
    return;
  }

  s.idleTime = 200;
  s.idleAnimation = chosen as IdleActivityState;
  s.idleAnimationFrame = 0;
  s.stateLocked = locked;
}

export function appendForceStateSection(body: HTMLElement, stateRef: { current: CatRuntimeState }) {
  body.appendChild(sectionLabel("force state"));

  const stateSelect = document.createElement("select");
  stateSelect.style.cssText = selectStyle;
  for (const name of ALL_STATES) {
    const opt = document.createElement("option");
    opt.value = name;
    opt.textContent = name;
    stateSelect.appendChild(opt);
  }

  const lockChk = document.createElement("input");
  lockChk.type = "checkbox";
  lockChk.title = "lock state (prevent auto-reset)";
  lockChk.style.cssText = `cursor:pointer;accent-color:${debugColor.accent};`;
  lockChk.addEventListener("change", () => {
    stateRef.current.stateLocked = lockChk.checked;
  });

  const lockLbl = document.createElement("label");
  lockLbl.title = "lock state";
  lockLbl.style.cssText = `display:flex;align-items:center;gap:3px;cursor:pointer;font-size:10px;color:${debugColor.accent};white-space:nowrap;`;
  lockLbl.appendChild(lockChk);
  lockLbl.append("lock");

  body.appendChild(makeRow(stateSelect));

